class SnapDocsApp {
    constructor() {
        // DOM Elements
        this.cameraSection = document.getElementById('camera-section');
        this.previewSection = document.getElementById('preview-section');
        this.gallerySection = document.getElementById('gallery-section');

        this.videoElement = document.getElementById('camera-preview');
        this.canvasElement = document.getElementById('capture-canvas');
        this.capturedImage = document.getElementById('captured-image');
        this.galleryGrid = document.getElementById('gallery-grid');

        // Buttons
        this.startCameraBtn = document.getElementById('start-camera-btn');
        this.captureBtn = document.getElementById('capture-btn');
        this.retakeBtn = document.getElementById('retake-btn');
        this.saveBtn = document.getElementById('save-btn');
        this.backToCameraBtn = document.getElementById('back-to-camera-btn');

        // Navigation
        this.navCamera = document.getElementById('nav-camera');
        this.navGallery = document.getElementById('nav-gallery');

        // State
        this.stream = null;
        this.currentCapture = null;
        this.documents = this.loadDocuments();

        // Initialize
        this.init();
    }

    /**
     * Initialize the application and set up event listeners
     */
    init() {
        this.setupEventListeners();
        this.renderGallery();
        this.checkCameraSupport();
    }

    /**
     * Check if the browser supports camera access
     */
    checkCameraSupport() {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            this.showToast('Camera access is not supported on this device', 'error');
            this.startCameraBtn.disabled = true;
        }
    }

    /**
     * Set up all event listeners
     */
    setupEventListeners() {
        // Camera controls
        this.startCameraBtn.addEventListener('click', () => this.startCamera());
        this.captureBtn.addEventListener('click', () => this.captureDocument());

        // Preview controls
        this.retakeBtn.addEventListener('click', () => this.retake());
        this.saveBtn.addEventListener('click', () => this.saveDocument());

        // Navigation
        this.navCamera.addEventListener('click', () => this.navigateToSection('camera-section'));
        this.navGallery.addEventListener('click', () => this.navigateToSection('gallery-section'));
        this.backToCameraBtn.addEventListener('click', () => this.navigateToSection('camera-section'));
    }

    /**
     * Start the camera stream
     */
    async startCamera() {
        try {
            // Request camera access with high-quality settings
            const constraints = {
                video: {
                    facingMode: 'environment', // Use back camera on mobile
                    width: { ideal: 1920 },
                    height: { ideal: 1080 }
                }
            };

            this.stream = await navigator.mediaDevices.getUserMedia(constraints);
            this.videoElement.srcObject = this.stream;

            // Update UI
            this.startCameraBtn.style.display = 'none';
            this.captureBtn.style.display = 'inline-flex';

            this.showToast('Camera started successfully', 'success');
        } catch (error) {
            console.error('Error accessing camera:', error);
            this.showToast('Failed to access camera. Please grant camera permissions.', 'error');
        }
    }

    /**
     * Stop the camera stream
     */
    stopCamera() {
        if (this.stream) {
            this.stream.getTracks().forEach(track => track.stop());
            this.videoElement.srcObject = null;
            this.stream = null;

            // Update UI
            this.startCameraBtn.style.display = 'inline-flex';
            this.captureBtn.style.display = 'none';
        }
    }

    /**
     * Capture a document from the camera feed
     */
    captureDocument() {
        const context = this.canvasElement.getContext('2d');

        // Set canvas dimensions to match video
        this.canvasElement.width = this.videoElement.videoWidth;
        this.canvasElement.height = this.videoElement.videoHeight;

        // Draw the current video frame to canvas
        context.drawImage(this.videoElement, 0, 0);

        // Convert to data URL
        this.currentCapture = this.canvasElement.toDataURL('image/jpeg', 0.9);

        // Stop camera and show preview
        this.stopCamera();
        this.showPreview();
    }

    /**
     * Show the preview section with the captured image
     */
    showPreview() {
        this.capturedImage.src = this.currentCapture;
        this.showSection('preview-section');
    }

    /**
     * Retake the photo
     */
    retake() {
        this.currentCapture = null;
        this.showSection('camera-section');
        this.startCamera();
    }

    /**
     * Save the captured document to local storage
     */
    saveDocument() {
        if (!this.currentCapture) {
            this.showToast('No document to save', 'error');
            return;
        }

        const document = {
            id: Date.now(),
