            timestamp: new Date().toISOString(),
            name: `Document_${new Date().toLocaleDateString().replace(/\//g, '-')}_${new Date().toLocaleTimeString().replace(/:/g, '-')}`
        };

        this.documents.push(document);
        this.saveDocuments();
        this.renderGallery();

        this.showToast('Document saved successfully!', 'success');
        this.currentCapture = null;

        // Navigate to gallery to show the saved document
